solution.java:
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        String[] reja = new String[n];
        int son = 0;
        for (int i = 0; i < n; i++) {
            String nom = in.next();
            int e = in.nextInt();
            int t = in.nextInt();
            int daraja = e * t;
            if (daraja >= 12 || t == 5) {
                reja[son] = nom + " " + daraja;
                son++;
            }
        }
        for (int i = 0; i < son; i++) System.out.println(reja[i]);
        System.out.println(son);
    }
}

