#include <iostream>
#include <string>
#include <vector>
using namespace std;

int main() {
    int n;
    cin >> n;
    vector<string> reja;
    for (int i = 0; i < n; i++) {
        string nom;
        int e, t;
        cin >> nom >> e >> t;
        int daraja = e * t;
        if (daraja >= 12 || t == 5) reja.push_back(nom + " " + to_string(daraja));
    }
    for (size_t i = 0; i < reja.size(); i++) cout << reja[i] << endl;
    cout << reja.size() << endl;
    return 0;
}
